 using namespace std;
 struct Node{
  char data;
  Node* next; 
 };

 struct queue{
  Node* head = nullptr;
  Node* tail = nullptr;
  void push_back(char x){
  Node* y = (Node *)malloc(sizeof(Node));
  y->data = x;
  if(head == nullptr){
  head = tail = y;
  }
  else{
  tail->next = y;
  tail = y;
  }
  }

  bool check(){
  if (head == nullptr) 
  return true;
  vector<char> v;
  for(Node* p = head; p != nullptr; p = p->next) v.push_back(p->data);
  int i = 0, j = (int)v.size() - 1;
  while(i < j){
  if (v[i] != v[j]) 
  return false;
  ++i; --j;
  }
  return true;
  }

  void clear(){
  while(head != nullptr){
  Node* temp = head;
  head = head->next;
  delete temp;
  }
  tail = nullptr;
  }
 };

 int main(){
  string ch;
  cin >> ch;
  queue q;

  for(int i; i < (int)ch.size(); ++i){
  q.push_back(ch[i]);
  }

  if(q.check()){
  cout << "YES\n";
  } 
  else{
  cout << "NO\n";
  }
  q.clear(); 
  return 0;
 }

