#include <bits/stdc++.h>
 using namespace std;

 struct sNode
 {
  int data;
  sNode *next;

  sNode(int val)
  {
  data = val;
  next = NULL;
  }
 };

 struct sStack
 {
  sNode *last = NULL;
  int count;

  bool isEmpty()
  {
  if (count == 0)
  return true;

  else
  return false;
  }

  int top()
  {
  if (isEmpty())
  {
  cout << "No element" << endl;
  return -1;
  }

  else
  {
  return last->data;
  }
  }

  void push(int num)
  {
  sNode *temp = new sNode(num);

  sNode *pr = last;
  last = temp;

  temp->next = pr;

  count++;
  }

  void pop()
  {
  if (count == 0)
  {
  cout << "Stack is empty" << endl;
  return;
  }

  sNode *pr = last;
  last = last->next;

  free(pr);

  count--;
  }

  void print()
  {
  sNode *it = last;

  while (it != NULL)
  {
  cout << it->data << " ";
  it = it->next;
  }

  cout << endl;
  }

  int size()
  {
  return count;
  }
 };

 void solve()
 {
  sStack st1, st2;
  string s;
  cin >> s;

  for (int i = 0; i < s.size(); i++)
  {
  st1.push(s[i]);
  }

  for (int i = s.size() - 1; i >= 0; i--)
  {
  st2.push(s[i]);
  }

  // st1.print();
  // st2.print();

  while (!st1.isEmpty())
  {
  if (st1.top() != st2.top())
  {
  cout << "NO" << endl;
  return;
  }

  st1.pop();
  st2.pop();
  }

  cout << "YES" << endl;
 }

 int main()
 {

  int t = 1;
  // cin >> t;

  while (t--)
  {
  solve();
  }
 }

