 int isPalindrome(char str[])
 {

  int size = strlen(str);
  int top = -1;

  char arr[size];

  for (int i; i < size; i++)
  {
  arr[++top] = str[i];
  }

  for (int i = 0; i < size; i++)
  {
  if (str[i] != arr[top--])
  {
