 };

 void push(struct node **head, char val){
  node *newnode = new node();
  newnode -> data = val;
  newnode -> next = NULL;
  if(*head == NULL) *head = newnode;
  else{
  newnode -> next = *head;
  *head = newnode;
  }

 }

 char pop(struct node **head){
  if(*head == NULL) return '\0';
  node *temp = *head;
  *head = temp -> next;
  char x = temp -> data;
  delete(temp);
  return x;

 }


