#include <iostream>
 #include <string>
 using namespace std;

 struct Node {
  char data;
  Node* next;
 };

 class Stack {
  Node* topNode;
 public:
  Stack() { topNode = nullptr; }

  void push(char x) {
  Node* newNode = new Node();
  newNode->data = x;
  newNode->next = topNode;
  topNode = newNode;
  }

  char pop() {
  if (topNode = nullptr) return '\0';
  char x = topNode->data;
  Node* temp = topNode;
  topNode = topNode->next;
  delete temp;
  return x;
  }

  bool empty() {
  return topNode == nullptr;
  }
 };

 bool isPalindrome(string s) {
  Stack st;
  for (char c : s) st.push(c);

  for (char c : s) {
  if (c != st.pop()) return false;
  }
  return true;
 }

 int main() {
  string s;
  while (cin >> s) {
  if (isPalindrome(s)) cout << "YES\n";
  else cout << "NO\n";
  }
  return 0;
 }

