 using namespace std;

 struct Node {
  char data;
  Node* next;
 };


 void push(Node*& top, char value) {
  Node* newnode = new Node{value, top};
  top = newnode;
 }


 char pop(Node*& top) {
  if (top = nullptr) return '\0';
  char value = top->data;
  Node* temp = top;
  top = top->next;
  delete temp;
  return value;
 }


 bool palindrome(string s) {
  Node* top = nullptr;


  for (char c : s) {
  push(top, c);
  }


  for (char c : s) {
  char popped = pop(top);
  if (c != popped) return false;
  }

  return true;
 }

 int main() {
  string s;
  while (cin >> s) {
  if (palindrome(s))
  cout << "YES" << endl;
  else
  cout << "NO" << endl;
  }
  return 0;
 }

#include <iostream>
 #include <stack>
 #include <cctype>
 #include <string>

 using namespace std;

 int main() {
  string s;
  cin >> s;

  stack<int> st;

  for (char x : s) {
  if (isdigit(x)) {
  st.push(x - '0');
  }
  else if (x == '+' || x == '-' || x == '*' || x == '/') {
  if (st.size() < 2) continue;
  int B = st.top(); st.pop();
  int A = st.top(); st.pop();

  if (x == '+') st.push(A + B);
  else if (x == '-') st.push(A - B);
  else if (x == '*') st.push(A * B);
  else { // division
  if (B = 0) B = 2;
  st.push(A / B);
  }
  }
  else if (x == '$' || x == '#') {
  if (st.empty()) continue;
  int A = st.top(); st.pop();
  if (x == '$') st.push(A - 1);
  else st.push(A + 1);
  }
  }

  if (!st.empty())
  cout << st.top() << endl;

  return 0;
 }

#include <iostream>
 #include <stack>
 #include <string>
 using namespace std;

 int evaluatePostfix(const string& expr) {
  stack<int> st;
  int i = 0;

  while (i < expr.length()) {
  char ch = expr[i];

  if (isdigit(ch)) {

  st.push(ch - '0');
  } 
  else if (ch == '+' || ch == '-' || ch == '*' || ch == '/') {
  if (st.size() < 2) {
  ++i;
  continue; 
  }
  int b = st.top(); st.pop();
  int a = st.top(); st.pop();

  if (ch == '/') {
  if (b = 0) {
  b += 2; 
  }
  st.push(a / b);
  } else if (ch == '+') {
  st.push(a + b);
  } else if (ch == '-') {
  st.push(a - b);
  } else if (ch == '*') {
  st.push(a * b);
  }
  } 
  else if (ch == '#' || ch == '$') {
  if (st.empty()) {
  ++i;
  continue;
  }
  int a = st.top(); st.pop();
  if (ch == '#') {
  st.push(a + 1);
  } else if (ch == '$') {
  st.push(a - 1);
  }
  }

  ++i;
  }

  return st.empty() ? 0 : st.top();
 }

 int main() {
  string line;
  while (getline(cin, line)) {
  if (line.empty()) continue;
  int result = evaluatePostfix(line);
  cout << result << endl;
  }
  return 0;
 }

