#include <iostream>
 #include <stack>
 #include <string>
 using namespace std;

 int evaluatePostfix(const string &exp) {
  stack<int> st;

  for (char c : exp) {
  if (isdigit(c)) {
  st.push(c - '0');
  }

  else if (c == '+') {
  int b = st.top(); st.pop();
  int a = st.top(); st.pop();
  st.push(a + b);
  }

  else if (c == '-') {
  int b = st.top(); st.pop();
  int a = st.top(); st.pop();
  st.push(a - b);
  }

  else if (c == '*') {
  int b = st.top(); st.pop();
  int a = st.top(); st.pop();
  st.push(a * b);
  }

  else if (c == '/') {
  int b = st.top(); st.pop();
  int a = st.top(); st.pop();
  if (b = 0) {
  b+=2;
  }
  st.push(a / b);
  }

  else if (c == '#') { 
  int a = st.top(); st.pop();
  st.push(a + 1);
  }

  else if (c == '$') { 
  int a = st.top(); st.pop();
  st.push(a - 1);
  }
  }

  return st.top();
 }

 int main() {
  string exp;
  while (cin >> exp) {
  cout << evaluatePostfix(exp) << "\n";
  }
  return 0;
 }

