 void pushfront(int a, struct node* &head) {
  struct node* temp = (struct node*)malloc(sizeof(struct node));
  temp->value = a;
  temp->next = head;
  head = temp;}

 void pushback(int a, struct node* &head) {
  struct node* temp = (struct node*)malloc(sizeof(struct node));
  temp->value = a;
  temp->next = NULL;

  if (head == NULL) {
  head = temp;
  } else {
  struct node* temp2 = head;
  while (temp2->next != NULL) {
  temp2 = temp2->next;
  }
  temp2->next = temp; }}

