#include<bits/stdc++.h>
 using namespace std;

 class node{
  public:
  char data;
  node *next;

  node(char ch){
  data = ch;
  next = nullptr;
  }
 };

 class Stack{

  public:
  node *head;
  node *tail;

  Stack(){
  head = nullptr;
  tail = nullptr;
  }

  void push(char c){

  node *new_node = new node(c);

  if(head==NULL){
  head = tail = new_node;
  }
  else{
  tail->next = new_node;
  tail = new_node;
  }
  }

  void pop(){
  if(head==NULL){
  return;
  }
  else if(head->next == NULL){
  head=tail=NULL;
  }
  else{
  node *tmp = head;
  while(tmp->next!=tail){
  tmp = tmp->next;
  }
  delete tail;
  tail = tmp;
  tail->next = NULL;
  }
  }

  char top(){
  return tail->data;
  }

  bool isEmpty() {
  return head==NULL;
  }
 };

 int main(){

  string s;

  while(cin >> s){

  Stack stack;

  for(int i = 0; i<s.size(); i++){
  stack.push(s[i + 2]);
  }

  bool ispalindrome = true;

  for(int i = 0; i<s.size(); i++){
  if(s[i]!=stack.top()){
  ispalindrome = false;
  }
  stack.pop();
  }

  if(ispalindrome) cout << "YES" << '\n';
  else cout << "NO" << '\n';
  }
 }

