 {
  int n;
  scanf("%d", &n);

  for(int i=1; i<n; i++)
  {
  int p, v;
  scanf("%d %d", &p, &v);

  if(p == 0)
  {
  pushhead(v);
  }

  else if(p == 1)
  {
  pushtail(v);
  }
  }

  for(int i=1; i<=n; i++)
  {
  int value = pophead();
  printf("%d", value);
  printf("\n");
  }

  return 0;
 }

