 #define Yes {cout<<"YES"<<endl;return;}
 #define No {cout<<"NO"<<endl;return;}


 void solve(){
  string s,a;
  getline(cin,s);
  getline(cin,a);
  ll n=s.size();
  ll m=a.size();
  char b[n];
  for(ll i=0;i<n;i++) b[i]=s[i];
  b[n]='\0';
  ll j=m-1;
  for(ll i=n-1;i>=0;i--){
  if(s[i]==a[j]){s[i]='=';j--;}
  if(j==-1) break;
  }
  if(j!=-1) {cout<<b<<endl;return;}
  for(ll i=0;i<n;i++){
  if(s[i]!='=')cout<<s[i];
  }
  cout<<endl;
 }



 int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  int t=1;
  //cin>>t;
  while(t--){solve();}
  return 0;
 }

